import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Link, useLocation, useNavigate, useParams } from 'react-router-dom';
import Typography from '@mui/material/Typography';
import Breadcrumbs from '@mui/material/Breadcrumbs';
import HomeBreadcrumbs from '../../Assets/Img/home-breadcrumbs.svg';
import PdfIcon from '../../Assets/Img/pdf-icon.svg';
import { Col, Row } from 'react-bootstrap';
import TextField from '@mui/material/TextField';
import Autocomplete from '@mui/material/Autocomplete';
import SearchOutlinedIcon from '@mui/icons-material/SearchOutlined';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';
import Pagination from '@mui/material/Pagination';
import Stack from '@mui/material/Stack';
import EventDashboard from './EventDashboard';
import { useDispatch, useSelector } from 'react-redux';
import {
  getEventListData,
  setActiveEventList,
} from 'store/reducers/Admin/Events/Parties/parties.slice';
import {
  withoutEventEnquiresList,
  yearEnquiresList,
} from 'store/reducers/Enquiry/Parties/enquireParties.slice';
import Loader from 'Components/Common/Loader';
import { yearsArray } from 'utils/FieldValues';
import { getPaginationData, getTotalPages } from 'utils/common';
import useSortable from 'utils/useSortable';
import moment from 'moment';
import DataNotFound from 'Components/Common/DataNotFound';
let pageSize = 10;

export default function Parties() {
  const params = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { activeEventList } = useSelector(({ parties }) => parties);
  const { withoutEventPartiesList, withoutEventPartiesLoading } = useSelector(
    ({ enquireParties }) => enquireParties,
  );

  const [searchVenue, setSearchVenue] = useState('');
  const [inputValue, setInputValue] = useState('');
  const [noVenueSearch, setNoVenueSearch] = useState('');
  const [eventsSearch, setEventsSearch] = useState('');
  const [currentPage, setCurrentPage] = useState({
    activeCurrentPage: 1,
  });

  const activeIndexOfLastItem = currentPage.activeCurrentPage * pageSize;
  const activeIndexOfFirstItem = activeIndexOfLastItem - pageSize;

  const { year } = useParams();
  const searchParams = new URLSearchParams(location.search);
  let paramObj = Object.fromEntries([...searchParams]);
  const [exclusive, setExclusive] = useState(false);

  const currentYear = new Date().getFullYear();

  const totalActiveRecordPage = useMemo(() => {
    const totalActiveRecordCount = getTotalPages(
      withoutEventPartiesList,
      pageSize,
    );
    return totalActiveRecordCount;
  }, [withoutEventPartiesList]);
  const setCurrentPartiesHandler = key => {
    setCurrentPage({
      ...currentPage,
      [key]: currentPage[key] - 1,
    });
  };
  const activeCurrentData = useMemo(() => {
    let currentDataList = getPaginationData(
      withoutEventPartiesList,
      currentPage.activeCurrentPage,
      pageSize,
      totalActiveRecordPage,
      setCurrentPartiesHandler,
      'activeCurrentPage',
    );
    return currentDataList;
  }, [withoutEventPartiesList, currentPage.activeCurrentPage]);

  useEffect(() => {
    const params = {};
    for (const [key, value] of searchParams) {
      params[key] = value;
    }
    if (Object?.keys(params)?.length > 0) {
      setSearchVenue(params);
    } else {
      // Reset the TABLE data if query params null
      setSearchVenue('');
    }

    dispatch(getEventListData());
    dispatch(
      withoutEventEnquiresList({
        event_id: params?.event_id ? params?.event_id : '',
        search: '',
        date: false,
      }),
    );
  }, [dispatch, location.search]);

  useEffect(() => {
    eventsSearch === '' && dispatch(getEventListData());
  }, [eventsSearch, dispatch]);

  const searchOption = useMemo(() => {
    let option =
      activeEventList?.map(data => ({
        _id: data?._id,
        year: data?.year,
        internalName: data?.internal_name,
      })) || [];
    if (inputValue) {
      option = option?.filter(
        option =>
          option?.internalName
            ?.toLowerCase()
            ?.includes(inputValue?.toLowerCase()) ||
          option?.year?.toString()?.includes(inputValue),
      );
    }
    return option;
  }, [activeEventList, inputValue]);

  const { itemsActive, requestSortActive } = useSortable(activeCurrentData);
  const filterOptionList = (options, value) => {
    let data = options?.filter(
      option =>
        option?.internalName?.toLowerCase()?.includes(value?.toLowerCase()) ||
        option?.year?.toString()?.includes(value),
    );

    return data;
  };

  const eventFilter = useCallback(() => {
    const filtered = activeEventList?.filter(
      item =>
        item?.internal_name
          ?.toLowerCase()
          ?.includes(eventsSearch?.toLowerCase()), // Assuming 'name' is the property to search for
    );
    dispatch(setActiveEventList(filtered));
  }, [activeEventList, eventsSearch, dispatch]);
  const handleExclusive = () => setExclusive(!exclusive);

  return (
    <div className="inner_wrapper">
      {withoutEventPartiesLoading && <Loader />}
      <div className="breadcrumb_wrap">
        <Breadcrumbs aria-label="breadcrumb">
          <Link to="/">
            <img src={HomeBreadcrumbs} alt="Home Icon" />
          </Link>
          {!(searchVenue || year) ? (
            <Typography>Parties</Typography>
          ) : (
            <Link to="/parties" onClick={() => setSearchVenue('')}>
              Parties
            </Link>
          )}
          {(searchVenue || year) && <Typography>Event Dashboard</Typography>}
        </Breadcrumbs>
      </div>
      <div className="page_title">
        <Row>
          <Col xs={9}>
            <h1>Events Dashboard</h1>
          </Col>
          <Col xs={3}>
            {/* <div className="form-group m-0">
              <Autocomplete
                disablePortal
                id="Filter-by-Venue"
                className="select_with_search"
                value={searchVenue}
                inputValue={inputValue}
                options={searchOption}
                getOptionLabel={option =>
                  option ? `${option.year} : ${option.internalName}` : ''
                }
                renderInput={params => <TextField {...params} />}
                // filterOptions={(options, state) => {
                //   return [];
                //   // return filterOptionList(options, inputValue);s
                // }}
                //   (options, { inputValue }) =>
                //   options.filter(
                //     option =>
                //       option.internalName
                //         .toLowerCase()
                //         .includes(inputValue.toLowerCase()) ||
                //       option.year.toString().includes(inputValue),
                //   )
                // }
                onChange={(event, newValue) => {
                  if (newValue && searchVenue?._id !== newValue._id) {
                    navigate(`/parties?event_id=${
                      newValue?._id ? newValue._id : ''
                    }&year=${
                      newValue?.year ? newValue.year : ''
                    }&internalName=${
                      newValue?.internalName ? newValue.internalName : ''
                    }
                    `);
                    // dispatch(
                    //   yearEnquiresList({
                    //     year: newValue?.year,
                    //     event_id: newValue?._id,
                    //     search: '',
                    //     is_exclusive: false,
                    //   }),
                    // );
                  }
                }}
                onInputChange={(event, newValue) => {
                  setInputValue(newValue);
                }}
              />
            </div> */}
          </Col>
        </Row>
      </div>
      <div className="parties_main_wrap parties_main_flex_wrap">
        <div className="parties_left_main_wrap">
          <div className="parties_left_inner_wrap bg_white_box p-3">
            <div className="search_wrapper_common mb-3">
              <input
                type="search"
                placeholder="Search"
                className="form-control"
                value={eventsSearch}
                onChange={e => setEventsSearch(e.target.value)}
              />
              <button className="btn_primary small" onClick={eventFilter}>
                <SearchOutlinedIcon />
              </button>
            </div>
            <ul>
              {activeEventList?.map((event, i) => {
                return (
                  <li
                    className={
                      paramObj.event_id === event?._id ? 'true' : 'false'
                    }
                    key={event?._id}
                    onClick={() => {
                      setExclusive(false);
                      navigate(
                        `/parties?event_id=${
                          event?._id ? event._id : ''
                        }&year=${event?.year ? event.year : ''}&internalName=${
                          event?.internal_name ? event.internal_name : ''
                        }
                      `,
                        {
                          state: {
                            event_sku: event?.sku,
                          },
                        },
                      );
                    }}
                  >
                    <span className="text_light">{event?.year} : </span>
                    {event?.internal_name}
                  </li>
                );
              })}
            </ul>
          </div>
        </div>
        <div className="parties_right_main_wrap">
          {searchVenue || year ? (
            <EventDashboard
              searchVenue={searchVenue}
              withoutEventPartiesList={withoutEventPartiesList}
              year={year}
              exclusive={exclusive}
              handleExclusive={handleExclusive}
            />
          ) : (
            <>
              {/*commets : not idea about system error*/}
              {/* <h4 className="fw_600">System Errors</h4>
          <p>Great! There are currently no unresolved errors logged</p> */}

              <div className="parties_table_Wrap">
                <Row className="align-items-center mb-3">
                  <Col xs={9}>
                    <h4 className="fw_600 m-0">
                      Enquiries with no venue assigned
                    </h4>
                  </Col>
                  <Col xs={3}>
                    <div className="search_wrapper_common">
                      <input
                        type="search"
                        placeholder="Search"
                        className="form-control"
                        value={noVenueSearch}
                        onChange={e => setNoVenueSearch(e.target.value)}
                      />
                      <button
                        className="btn_primary small"
                        onClick={() =>
                          dispatch(
                            withoutEventEnquiresList({
                              event_id: searchVenue ? searchVenue?._id : '',
                              search: noVenueSearch,
                              date: false,
                            }),
                          )
                        }
                      >
                        <SearchOutlinedIcon />
                      </button>
                    </div>
                  </Col>
                </Row>
              </div>
              <div className="table_main_Wrapper vertical_top mb-3">
                <TableContainer component={Paper}>
                  <Table sx={{ minWidth: 650 }} aria-label="simple table">
                    <TableHead>
                      <TableRow>
                        <TableCell>
                          <span onClick={() => requestSortActive('date')}>
                            Date
                          </span>
                        </TableCell>
                        <TableCell>
                          <span onClick={() => requestSortActive('enquired')}>
                            Enquiries
                          </span>
                        </TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {itemsActive?.map((data, index) => {
                        //Action on when data.date == not specified
                        return (
                          <TableRow key={index}>
                            <TableCell>
                              {data?.created_at
                                ? moment(data?.created_at).format(
                                    'ddd Do MMM YYYY',
                                  )
                                : 'No Date Specified'}
                            </TableCell>
                            <TableCell>
                              <Link
                                to={`/enquiries/${
                                  data?.created_at
                                    ? moment(data?.created_at).format(
                                        'YYYY-MM-DD',
                                      )
                                    : 'Invalid Date'
                                }?date=true`}
                              >
                                {data?.places}
                              </Link>
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                </TableContainer>
                <div className="table_pagination_wrap">
                  {itemsActive?.length > 0 ? (
                    <Row className="g-0 align-items-center my-2">
                      <Col sm={6}>
                        <div className="total_entry">
                          <p className="m-0">
                            Showing {activeIndexOfFirstItem + 1} to{' '}
                            {Math.min(
                              activeIndexOfLastItem,
                              withoutEventPartiesList?.length,
                            )}{' '}
                            of {withoutEventPartiesList?.length} entries
                          </p>
                        </div>
                      </Col>
                      <Col sm={6}>
                        <div className="pagination_wrap">
                          <Stack spacing={2}>
                            <Pagination
                              count={totalActiveRecordPage}
                              page={currentPage.activeCurrentPage}
                              onChange={(e, page) =>
                                setCurrentPage({
                                  ...currentPage,
                                  activeCurrentPage: page,
                                })
                              }
                            />
                          </Stack>
                        </div>
                      </Col>
                    </Row>
                  ) : (
                    <DataNotFound />
                  )}
                </div>
              </div>
              <div className="years_number_Wrap mb-3">
                <h4 className="fw_600">This Years' Numbers</h4>
                <p>Click the PDF icon to view as PDF</p>
                <ul className="pdf_link_wrap">
                  <li>
                    <Link to={`/location-event-data/All`} target="_blank">
                      <div className="pdf_icon">
                        <img src={PdfIcon} alt="pdf icon" />
                      </div>
                      <div className="pdf_text">
                        <p>View booking numbers for all events here</p>
                      </div>
                    </Link>
                  </li>
                </ul>
              </div>
              <div className="years_number_Wrap mb-3">
                <h4 className="fw_600">Previous Years' Numbers</h4>
                <p>Click the PDF icon to view as PDF</p>
                <ul className="pdf_link_wrap">
                  {yearsArray
                    ?.slice(0)
                    .reverse()
                    .map((preYear, index) => {
                      return (
                        <li key={index}>
                          <Link
                            to={`/location-event-data/${preYear}`}
                            target="_blank"
                          >
                            <div className="pdf_icon">
                              <img src={PdfIcon} alt="pdf icon" />
                            </div>
                            <div className="pdf_text">
                              <p>
                                View booking numbers for all events from{' '}
                                {preYear}
                              </p>
                            </div>
                          </Link>
                        </li>
                      );
                    })}
                </ul>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
